import { getSelectorProjectList } from '~/client';
import type { GetSelectorProjectListResponse, ProjectStatus, ProjectType, GetSelectorProjectListData } from '~/client';

export const useSelectorProjectList = defineQuery(() => {
  const projectStatuses = ref<ProjectStatus[]>(['active']);
  const projectType = ref<ProjectType | null>(null);

  const { data, isLoading, error } = useQuery({
    key: () => ['selector-project-list', projectStatuses.value, projectType.value],
    query: (): Promise<GetSelectorProjectListResponse> =>
      getSelectorProjectList({
        composable: '$fetch',
        query: { statuses: projectStatuses.value, ...(projectType.value && { type: projectType.value }) },
      }),
  });

  function resetFilters() {
    projectStatuses.value = ['active'];
    projectType.value = null;
  }

  return {
    projectType,
    projectStatuses,
    projects: computed(() => data.value?.items ?? null),
    isLoading,
    error,
    resetFilters,
  };
});
